-- 13F catch-up events (a manager files 4+ original 13F reports on one day, each 1+ year after its quarter ended): manager name, city, CRD and file numbers from the cover page, one accession per event
SELECT ACCESSION_NUMBER, FILINGMANAGER_NAME, FILINGMANAGER_CITY, FILINGMANAGER_STATEORCOUNTRY, CRDNUMBER, SECFILENUMBER, FORM13_FFILENUMBER, REPORTTYPE, ISAMENDMENT, LEFT(ADDITIONALINFORMATION, 300) addl, SRC_FILE
FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_13F_FILERS WHERE ACCESSION_NUMBER IN ('0002043130-25-000005')